<?php
declare(strict_types=1);
namespace EPejabat\Core;
final class Web {
    public function __construct(private \PDO $p,private ?array $user){}
    private function actor():int {if(!$this->user)Support::redirect('/login');return (int)$this->user['id'];}
    private function can(string $perm):bool {return $this->user&&Authorization::any($this->p,(int)$this->user['id'],$perm);}
    private static function e(mixed $s):string {return Support::escape($s);}
    private static function input(string $key,string $label,mixed $value='',string $type='text',bool $required=true):string {return '<label>'.self::e($label).'<input name="'.self::e($key).'" type="'.self::e($type).'" value="'.self::e($value).'" maxlength="'.($type==='password'?72:1000).'"'.($required?' required':'').($type==='password'?' autocomplete="new-password"':'').'></label>';}
    private static function form(string $action,string $fields,string $button='Simpan',bool $upload=false):string {return '<form method="post"'.($upload?' enctype="multipart/form-data"':'').'><input type="hidden" name="csrf" value="'.Support::csrf().'"><input type="hidden" name="action" value="'.self::e($action).'">'.$fields.'<button>'.self::e($button).'</button></form>';}
    private function select(string $key,string $label,array $rows,mixed $value=null,bool $required=false):string {$out='<label>'.self::e($label).'<select name="'.self::e($key).'"'.($required?' required':'').'><option value="">— Pilih —</option>';foreach($rows as $r)$out.='<option value="'.self::e($r['id']).'"'.((string)$value===(string)$r['id']?' selected':'').'>'.self::e($r['name']).'</option>';return $out.'</select></label>';}
    private function masters(string $cat):array {return Database::query($this->p,'SELECT id,name FROM master_data WHERE category=? AND is_active=1 ORDER BY name',[$cat])->fetchAll();}
    private function orgs(string $perm='core.staff.manage',bool $public=false):array {if($public)return $this->p->query('SELECT id,name FROM organisations WHERE is_active=1 ORDER BY name')->fetchAll();[$s,$a]=Authorization::scope($this->p,$this->actor(),$perm,'o.id');return Database::query($this->p,'SELECT o.id,o.name FROM organisations o WHERE o.is_active=1 AND '.$s.' ORDER BY o.name',$a)->fetchAll();}
    private function table(array $rows,array $columns,?callable $action=null):string {$h='<div class="table-wrap"><table><thead><tr>';foreach($columns as $label)$h.='<th>'.self::e($label).'</th>';if($action)$h.='<th>Tindakan</th>';$h.='</tr></thead><tbody>';foreach($rows as $r){$h.='<tr>';foreach($columns as $key=>$label)$h.='<td>'.self::e($r[$key]??'').'</td>';if($action)$h.='<td>'.$action($r).'</td>';$h.='</tr>';}if(!$rows)$h.='<tr><td colspan="'.(count($columns)+($action?1:0)).'">Tiada rekod.</td></tr>';return $h.'</tbody></table></div>';}
    private function render(string $title,string $body,string $message=''):never {
        $nav='<a href="/">Utama</a>';if($this->user){$nav.='<a href="/dashboard">Dashboard</a><a href="/profile">Profil saya</a><a href="/my-organisation">Organisasi saya</a><a href="/notifications">Notifikasi</a><a href="/security">Keselamatan akaun</a>';foreach(['/staff'=>['core.staff.view','Direktori staf'],'/registry'=>['core.staff.manage','Registry staf'],'/registration-admin'=>['core.registrations.review','Staff Administration'],'/registrations'=>['core.registrations.review','Permohonan'],'/organisations'=>['core.organisations.manage','Organisasi'],'/master-data'=>['core.master.manage','Master data'],'/roles'=>['core.roles.manage','Role & akses'],'/documents'=>['core.documents.view','Dokumen'],'/audit'=>['core.audit.view','Audit'],'/settings'=>['core.settings.manage','Konfigurasi'],'/modules'=>['core.modules.manage','Modul'],'/upgrade'=>['core.migrations.manage','Upgrade']] as $url=>$spec)if($this->can($spec[0]))$nav.='<a href="'.$url.'">'.$spec[1].'</a>';if(Authorization::super($this->p,(int)$this->user['id'])||$this->can('training.dashboard.view'))$nav.='<a href="/training">Latihan &amp; CPD</a><a href="/training/history">Sejarah latihan</a>'; if(Authorization::super($this->p,(int)$this->user['id'])||$this->can('eforms.submissions.create')||$this->can('eforms.templates.manage')||$this->can('eforms.submissions.review'))$nav.='<a href="/eforms">e-Forms</a>';$nav.=self::form('logout','','Log keluar');}else{$nav.='<a href="/login">Log masuk</a><a href="/claim">Aktifkan akaun</a><a href="/register">Mohon pendaftaran</a>';}
        Ui::layout($title,($message?'<p class="notice" role="status">'.self::e($message).'</p>':'').$body,$nav);
    }
    private static function passwordInput(string $key):string {$v=$_POST[$key]??'';if(!is_string($v)||strlen($v)>72||str_contains($v,"\0"))throw new \InvalidArgumentException('Input kata laluan tidak sah.');return $v;}
    private static function postId(string $k,bool $nullable=false):?int {return Core::id($_POST[$k]??null,$nullable);}
    private function requireAny(string $perm):void {if(!$this->can($perm)){http_response_code(403);throw new \RuntimeException('Akses tidak dibenarkan.');}}
    public function handle(string $path):never {
        if($path==='/eforms'){foreach(['Schema','Service','Migrations','Web'] as $file)require_once APP_ROOT.'/app/Modules/EForms/'.$file.'.php';\EPejabat\Modules\EForms\Web::handle($this->p,$this->user);}
        if($path==='/activate'&&isset($_GET['token'])){try{$t=Core::text($_GET['token'],64);Accounts::token($this->p,$t);$_SESSION['account_token']=$t;Support::redirect('/activate');}catch(\RuntimeException|\InvalidArgumentException $e){unset($_SESSION['account_token']);http_response_code(400);$this->render('Jemputan tidak sah','<p>Pautan tidak sah, telah digunakan atau tamat tempoh. Minta jemputan baharu daripada Admin atau <a href="/claim">mohon semula</a>. Tiada password atau akaun ditukar.</p>');}}
        $message='';if($_SERVER['REQUEST_METHOD']==='POST'){Support::checkCsrf();try{$message=$this->action(Support::post('action',40));}catch(\PDOException $e){$message='Permintaan tidak dapat diproses. Rujukan: '.Support::log($e);}catch(\RuntimeException|\InvalidArgumentException $e){$message=$e->getMessage();}}
        try{$body=match($path){'/','/index.php'=>$this->home(),'/dashboard'=>$this->dashboard(),'/claim'=>$this->claim(),'/register'=>$this->registration(),'/forgot-password'=>$this->forgot(),'/activate'=>$this->activation(),'/profile'=>$this->profile(),'/security'=>$this->security(),'/my-organisation'=>$this->myOrganisation(),'/staff'=>$this->directory(),'/registry'=>$this->registry(),'/registrations'=>$this->reviews(),'/organisations'=>$this->organisations(),'/master-data'=>$this->master(),'/roles'=>$this->roles(),'/notifications'=>$this->notifications(),'/settings'=>$this->settings(),'/modules'=>$this->modules(),'/documents'=>$this->documents(),'/download'=>$this->download(),'/audit'=>$this->audit(),default=>$this->missing()};}catch(\RuntimeException|\InvalidArgumentException $e){if(http_response_code()<400)http_response_code(400);$body='<p class="error">'.self::e($e instanceof \PDOException?'Permintaan tidak tersedia.':$e->getMessage()).'</p>';}
        $titles=['/dashboard'=>'Dashboard','/claim'=>'Aktifkan akaun staf','/register'=>'Permohonan pendaftaran','/forgot-password'=>'Lupa kata laluan','/activate'=>'Cipta kata laluan / pengesahan pautan','/profile'=>'Dashboard Profil Staf','/security'=>'Keselamatan akaun','/my-organisation'=>'Organisasi saya','/staff'=>'Direktori staf','/registry'=>'Pre-Verified Staff Registry','/registrations'=>'Semakan pendaftaran','/organisations'=>'Pengurusan organisasi','/master-data'=>'Shared Master Data','/roles'=>'Role & Permission','/notifications'=>'Pusat notifikasi','/settings'=>'Konfigurasi sistem','/modules'=>'Module Registry','/documents'=>'Dokumen','/audit'=>'Audit'];$this->render($titles[$path]??'epejabat.net',$body,$message);
    }
    private function action(string $a):string {
        $p=$this->p;$public=['claim','register','reset_request','activate'];$actor=in_array($a,$public,true)?0:$this->actor();
        switch($a){
            case 'portal_branding':if(!Authorization::super($p,$actor))throw new \RuntimeException('Super Admin diperlukan.');$name=Core::text(Support::post('portal_name',120),120);if($name==='')throw new \InvalidArgumentException('Nama portal diperlukan.');Core::tx($p,function()use($p,$actor,$name){$old=Database::query($p,"SELECT setting_value FROM system_settings WHERE setting_key='portal_name'")->fetchColumn();Versions::set($p,'portal_name',$name);Audit::record($p,'portal.branding_changed',$actor,null,'portal_name','core',null,['name'=>$old?:null],['name'=>$name]);});return 'Identiti portal dikemas kini.';
            case 'logout':Auth::logout($p);Support::redirect('/login');
            case 'claim':return Accounts::claim($p,Support::post('email',190),Support::post('full_name',190));
            case 'register':return Accounts::request($p,$_POST,$this->user?(int)$this->user['id']:null);
            case 'reset_request':return Accounts::resetRequest($p,Support::post('email',190));
            case 'activate':$t=$_SESSION['account_token']??'';$info=Accounts::token($p,$t);$password=self::passwordInput('password');if(in_array($info['purpose'],['claim','reset'],true)&&$password!==($_POST['confirm_password']??null))throw new \InvalidArgumentException('Pengesahan kata laluan tidak sepadan.');Accounts::consume($p,$t,$password,$_POST);unset($_SESSION['account_token']);return 'Pengesahan berjaya. Anda boleh log masuk; pembetulan permohonan akan disemak semula.';
            case 'staff_invite':Accounts::invite($p,$actor,self::postId('staff_id'),Support::post('reason',500));return 'Jemputan dimasukkan ke queue; SMTP accepted dan account activation dipaparkan berasingan.';
            case 'facility_batch_apply':$districts=$_POST['districts']??[];if(!is_array($districts))throw new \InvalidArgumentException('Pilihan tidak sah.');$r=FacilityDirectory::apply($p,$actor,$districts,isset($_POST['rename_kota_bharu']),Support::post('reason',500),Support::post('preview_hash',64),isset($_POST['confirmed']));return 'Batch fasiliti selesai: '.count(array_filter($r,fn($x)=>$x['status']==='IMPORTED')).' rekod ditambah; rekod sedia ada dikekalkan.';
            case 'activation_resume':StaffActivationRecovery::resume($p,$actor,self::postId('staff_id'),Support::post('email',190),Support::post('confirmed_name',190),Support::post('reason',500));return 'Rekod PRE_VERIFIED asal disambung. Jemputan password pertama dimasukkan ke queue; Staff ID tidak berubah.';
            case 'preverify':$existingId=Staff::preverify($p,$actor,$_POST);$existingAccount=Database::query($p,'SELECT is_active FROM users WHERE staff_identity_id=?',[$existingId])->fetch();if($existingAccount)return $existingAccount['is_active']?'E-mel ini dipautkan kepada akaun staf sedia ada. Staff ID dan password dikekalkan. Gunakan e-mel login asal atau Lupa kata laluan; tiada jemputan password baharu dihantar.':'Akaun staf sedia ada tidak aktif. Semak status akaun melalui pentadbir; tiada password atau status ditukar.';return 'Staff ID dikekalkan. Jemputan dimasukkan ke queue; maklumat profil lain boleh dilengkapkan selepas activation.';
            case 'profile_address':RegistrationMaster::savePrivateProfile($p,$actor,self::postId('staff_id'),$_POST);return 'Alamat pilihan disimpan; penempatan rasmi tidak berubah.';
            case 'profile_draft':RegistrationMaster::saveDeclaration($p,$actor,self::postId('staff_id'),$_POST);return 'Maklumat pilihan disimpan sebagai SELF_DECLARED; data verified dan akses rasmi tidak berubah.';
            case 'profile_professional':RegistrationMaster::requestProfessional($p,$actor,self::postId('staff_id'),$_POST);return 'Permohonan profesional menunggu verification Admin.';
            case 'profile_email_request':RegistrationMaster::emailContactRequest($p,$actor,Support::post('contact_email',190));return 'Pengesahan pemilikan dimasukkan ke queue; bukan bukti e-mel dihantar.';
            case 'profile_email_verify':RegistrationMaster::emailContactVerify($p,$actor,Support::post('contact_token',64));return 'Pemilikan disahkan; identity approval Admin masih diperlukan.';
            case 'profile_notification':RegistrationMaster::notificationContact($p,$actor,self::postId('contact_id'));return 'Pilihan notifikasi disimpan.';
            case 'profile':Staff::edit($p,$actor,self::postId('staff_id'),$_POST);return 'Profil dikemas kini.';
            case 'employment':Staff::employmentChange($p,$actor,self::postId('staff_id'),$_POST);return 'Sejarah perkhidmatan direkodkan.';
            case 'credential':Staff::credential($p,$actor,self::postId('staff_id'),$_POST);return 'Maklumat profesional disimpan.';
            case 'registry_status':Staff::registryStatus($p,$actor,self::postId('staff_id'),Support::post('status',30),Support::post('reason',500));return 'Status registry disimpan.';
            case 'account_status':Staff::accountStatus($p,$actor,self::postId('user_id'),Support::post('is_active',1)==='1',Support::post('reason',500));return 'Status akaun dikemas kini.';
            case 'password_change':if(self::passwordInput('password')!==self::passwordInput('confirm_password'))throw new \InvalidArgumentException('Pengesahan tidak sepadan.');Accounts::changePassword($p,$actor,self::passwordInput('current_password'),self::passwordInput('password'));Auth::logout($p);Support::redirect('/login');
            case 'email_change':Accounts::changeEmail($p,$actor,Support::post('email',190),self::passwordInput('current_password'));return 'Pautan pengesahan e-mel baharu dimasukkan ke queue; approval Admin diperlukan sebelum perubahan. E-mel semasa kekal sehingga pengesahan berjaya.';
            case 'organisation_full_name':OrganisationNaming::rename($p,$actor);return 'Nama penuh Kota Bharu diseragamkan pada rekod organisasi ID 3. Semua paparan berasaskan rekod semasa akan menggunakan nama penuh.';
            case 'organisation':Organisations::save($p,$actor,$_POST,self::postId('id',true));return 'Organisasi disimpan.';
            case 'master':MasterData::save($p,$actor,$_POST,self::postId('id',true));return 'Master data disimpan.';
            case 'role_define':Roles::manageDefinition($p,$actor,$_POST);return 'Role dan permission disimpan.';
            case 'role_assign':Roles::assign($p,$actor,self::postId('user_id'),self::postId('role_id'),self::postId('organisation_id',true),isset($_POST['include_descendants']),Support::post('reason',500));return 'Role diberikan.';
            case 'role_revoke':Roles::revoke($p,$actor,self::postId('assignment_id'),Support::post('reason',500));return 'Role dibatalkan.';
            case 'review':Accounts::review($p,$actor,self::postId('request_id'),Support::post('decision',30),Support::post('reason',500));return 'Keputusan direkodkan.';
            case 'notification_read':Database::query($p,'UPDATE notifications SET read_at=UTC_TIMESTAMP() WHERE id=? AND user_id=?',[self::postId('notification_id'),$actor]);return 'Notifikasi ditanda dibaca.';
            case 'mail_single_retry':$r=Notifications::processOne($p,$actor,Core::id($_POST['delivery_id']??null),Core::email($_POST['approved_recipient']??''));return $r['blocked']?'SMTP belum dikonfigurasi; tiada e-mel dihantar.':'Delivery terpilih: accepted '.$r['sent'].'; gagal '.$r['failed'].'. Jika 0/0, semak backoff next attempt.';
            case 'mail_process':Authorization::require($p,$actor,'core.notifications.manage');$r=Notifications::process($p,10);return $r['blocked']?'SMTP belum dikonfigurasi; tiada e-mel dihantar.':'SMTP menerima '.$r['sent'].' e-mel; '.$r['failed'].' cubaan gagal. Penghantaran ke inbox belum dipastikan.';
            case 'mail_test':Authorization::require($p,$actor,'core.notifications.manage');Notifications::enqueue($p,$this->user['email'],'system',['message'=>'Ujian penghantaran epejabat.']);return 'Ujian dimasukkan ke queue. Jalankan queue dan semak inbox.';
            case 'template':Authorization::require($p,$actor,'core.notifications.manage');Core::tx($p,function()use($p,$actor){$key=Support::post('template_key',64);$subject=Core::text(Support::post('subject',190));$body=Core::text(Support::post('body',5000),5000);$r=Database::query($p,'SELECT * FROM notification_templates WHERE template_key=? FOR UPDATE',[$key])->fetch();if(!$r)throw new \InvalidArgumentException('Template tidak wujud.');if(in_array($key,['activation','reset','correction'],true)&&!str_contains($body,'{{url}}'))throw new \InvalidArgumentException('Template mesti mempunyai {{url}}.');Database::query($p,'UPDATE notification_templates SET subject=?,body=? WHERE template_key=?',[$subject,$body,$key]);Audit::record($p,'notification.template_changed',$actor,null,$key,'core',null,$r,['subject'=>$subject,'body'=>$body]);});return 'Template disimpan.';
            case 'module':Authorization::require($p,$actor,'core.modules.manage');$key=Support::post('module_key',64);$status=Support::post('status',20);if(!preg_match('/\A[a-z][a-z0-9_]{1,63}\z/',$key)||!in_array($status,['active','inactive'],true))throw new \InvalidArgumentException('Modul tidak sah.');if($key==='core'||$key==='eforms'&&$status==='active'||$key==='training')throw new \InvalidArgumentException('Core dilindungi; modul operasi belum tersedia.');$nav=Support::post('navigation_path',190);if($nav!==''&&!preg_match('#\A/[a-z0-9/_-]+\z#',$nav))throw new \InvalidArgumentException('Navigasi mesti path dalaman.');Core::tx($p,function()use($p,$actor,$key,$status,$nav){Database::query($p,'INSERT INTO module_registry(module_key,name,status,navigation_path,permission_namespace) VALUES(?,?,?,?,?) ON DUPLICATE KEY UPDATE name=VALUES(name),status=VALUES(status),navigation_path=VALUES(navigation_path)',[$key,Core::text(Support::post('name',190)),$status,$nav?:null,$key]);Audit::record($p,'module.updated',$actor,null,$key);});return 'Module registry disimpan.';
            case 'document_upload':Documents::upload($p,$actor,self::postId('organisation_id'),Support::post('module_code',64),Support::post('title',190),$_FILES['file']??[],self::postId('document_id',true));return 'Dokumen dimuat naik.';
            case 'document_status':Documents::status($p,$actor,self::postId('document_id'),Support::post('status',20),Support::post('reason',500));return 'Status dokumen disimpan.';
            case 'import_preview':$f=$_FILES['file']??[];if(($f['error']??1)!==UPLOAD_ERR_OK||!is_uploaded_file($f['tmp_name']??''))throw new \InvalidArgumentException('Upload import gagal.');$mapping=[];foreach(Imports::HEADERS as $column){$source=Core::text($_POST['map_'.$column]??'',100,false);if($source!=='')$mapping[$source]=$column;}$rows=Imports::read($f['tmp_name'],strtolower(pathinfo($f['name'],PATHINFO_EXTENSION)),$mapping);$batch=Imports::preview($p,$actor,$rows);Support::redirect('/registry?batch='.$batch);
            case 'import_commit':Imports::commit($p,$actor,self::postId('batch_id'));return 'Import diproses. Semak keputusan setiap baris.';
            default:throw new \InvalidArgumentException('Tindakan tidak sah.');
        }
    }
    private function home():string {return Ui::home($this->p,$this->user);}
    private function dashboard():string {
        $u=$this->actor();$h='<section class="card"><h2>Dashboard Profil Staf</h2><p>Maklumat tambahan adalah pilihan.</p><a class="button" href="/profile">Buka dashboard profil saya</a></section><section class="welcome-panel"><div><p class="eyebrow">DASHBOARD ANDA</p><h2>Selamat datang, '.self::e($this->user['full_name']).'.</h2><p>Ringkasan sebenar berdasarkan akses dan organisasi anda.</p></div><a class="button secondary" href="/profile">Lihat profil</a></section>';$h.='<div class="stats">';$unread=(int)Database::query($this->p,'SELECT COUNT(*) FROM notifications WHERE user_id=? AND read_at IS NULL',[$u])->fetchColumn();$metrics=['Notifikasi belum dibaca'=>$unread];
        if($this->can('core.staff.view')){[$s,$a]=Authorization::scope($this->p,$u,'core.staff.view','p.organisation_id');$metrics['Staf dalam scope']=(int)Database::query($this->p,'SELECT COUNT(*) FROM staff_profiles p WHERE '.$s,$a)->fetchColumn();$metrics['Akaun aktif']=(int)Database::query($this->p,'SELECT COUNT(*) FROM users u JOIN staff_profiles p ON p.staff_identity_id=u.staff_identity_id WHERE u.is_active=1 AND '.$s,$a)->fetchColumn();$metrics['Akaun tidak aktif']=(int)Database::query($this->p,'SELECT COUNT(*) FROM users u JOIN staff_profiles p ON p.staff_identity_id=u.staff_identity_id WHERE u.is_active=0 AND '.$s,$a)->fetchColumn();$metrics['Jumlah akaun']=$metrics['Akaun aktif']+$metrics['Akaun tidak aktif'];$metrics['Profil belum lengkap']=(int)Database::query($this->p,"SELECT COUNT(*) FROM staff_profiles p WHERE (p.profession_id IS NULL OR p.position_id IS NULL OR p.grade_id IS NULL OR p.phone IS NULL OR p.phone='') AND ".$s,$a)->fetchColumn();}
        if($this->can('core.registrations.review')){[$s,$a]=Authorization::scope($this->p,$u,'core.registrations.review','organisation_id');$metrics['Permohonan menunggu']=(int)Database::query($this->p,"SELECT COUNT(*) FROM registration_requests WHERE status='PENDING_VERIFICATION' AND ".$s,$a)->fetchColumn();}
        if($this->can('core.organisations.manage')){[$s,$a]=Authorization::scope($this->p,$u,'core.organisations.manage','id');$metrics['Organisasi']=(int)Database::query($this->p,'SELECT COUNT(*) FROM organisations WHERE '.$s,$a)->fetchColumn();$metrics['PKD']=(int)Database::query($this->p,"SELECT COUNT(*) FROM organisations WHERE type='pkd' AND ".$s,$a)->fetchColumn();$metrics['Klinik / unit']=(int)Database::query($this->p,"SELECT COUNT(*) FROM organisations WHERE type IN ('clinic','facility','unit') AND ".$s,$a)->fetchColumn();}
        foreach($metrics as $k=>$v)$h.='<section class="stat"><span>'.self::e($k).'</span><strong>'.$v.'</strong></section>';$h.='</div><section class="card module-hub"><h2>Perkhidmatan & modul</h2><p>Pilih ruang kerja yang tersedia untuk akaun anda.</p><div class="module-grid">';$modules=$this->p->query("SELECT * FROM module_registry WHERE status='active'")->fetchAll();foreach($modules as $m){if($m['module_key']==='core'||Authorization::super($this->p,$u)||$this->can($m['module_key'].'.dashboard.view'))$h.='<article class="module-tile"><span class="badge">MODUL AKTIF</span><h3>'.self::e($m['name']).'</h3>'.($m['navigation_path']?'<a class="button" href="'.self::e($m['navigation_path']).'">Buka ruang kerja →</a>':'').'</article>';}$h.='</div></section>';if($this->can('core.settings.manage'))$h.='<p>SMTP: '.(Notifications::config()?'Dikonfigurasi; semak ujian penghantaran.':'Belum dikonfigurasi — e-mel belum dihantar.').'</p>';return $h;
    }
    private function claim():string {return '<p>Untuk staf yang telah disenaraikan dan disahkan oleh pentadbir. Pengaktifan memerlukan bukti pemilikan e-mel.</p>'.self::form('claim',self::input('full_name','Nama penuh seperti dalam registry').self::input('email','E-mel rasmi','','email'),'Hantar pautan pengesahan').'<p><a href="/register">Belum tersenarai? Mohon pendaftaran.</a></p>';}
    private function registration():string {if(RegistrationMaster::ready($this->p))return RegistrationWeb::form($this->p);return '<p>Permohonan akan disemak oleh pentadbir organisasi. Akaun belum aktif sehingga kelulusan dan pengesahan e-mel.</p>'.self::form('register',self::input('full_name','Nama penuh').self::input('email','E-mel rasmi','','email').$this->select('organisation_id','Organisasi / klinik / unit semasa',$this->orgs(public:true),null,true).$this->select('profession_id','Profesion',$this->masters('profession')),'Hantar permohonan');}
    private function forgot():string {return self::form('reset_request',self::input('email','E-mel akaun','','email'),'Hantar pautan reset').'<p><a href="/login">Kembali ke log masuk</a></p>';}
    private function activation():string {if(!isset($_SESSION['account_token']))return '<p>Buka pautan yang dihantar ke e-mel anda. Jika pengesahan sudah berjaya, <a href="/login">log masuk di sini</a>.</p>';$t=Accounts::token($this->p,$_SESSION['account_token']);$fields=match($t['purpose']){'correction'=>self::input('full_name','Nama penuh yang dibetulkan').$this->select('profession_id','Profesion',$this->masters('profession')),'registration_verify'=>'<p>Sahkan pemilikan e-mel. Semakan identiti Admin masih diperlukan; langkah ini tidak mengaktifkan akaun.</p>','emailchange'=>'<p>Sahkan penggunaan e-mel baharu.</p>',default=>self::input('password','Kata laluan baharu (12–72 bait)','','password').self::input('confirm_password','Sahkan kata laluan','','password')};return '<p>Pautan ini sekali guna dan mempunyai tempoh sah.</p>'.self::form('activate',$fields,'Sahkan');}
    private function employmentFields(array $r=[]):string {$h=$this->select('organisation_id','Organisasi semasa (pilih unit jika ditempatkan di unit)',$this->orgs(),$r['organisation_id']??null,true);foreach(['profession'=>'Profesion','position'=>'Jawatan','grade'=>'Gred','employment_status'=>'Status perkhidmatan'] as $k=>$v)$h.=$this->select($k.'_id',$v,$this->masters($k),$r[$k.'_id']??null);$h.=$this->select('facility_id','Fasiliti induk (pilihan)',$this->orgs(),$r['facility_id']??null).$this->select('unit_id','Unit sama dengan organisasi semasa (pilihan)',$this->orgs(),$r['unit_id']??null);return $h;}
    private function profile():string {
