        $h='<p><a class="button" href="/profile?id='.$id.'">Kembali ke Ringkasan Profil</a></p>'.$h;$h.='<p><a href="/registration-contact?id='.$id.'">Contact & privacy</a></p>'; $current=['organisation'=>'Belum ditetapkan'];if($org)$current['organisation']=Database::query($this->p,'SELECT name FROM organisations WHERE id=?',[$org])->fetchColumn();foreach(['profession','position','grade','employment_status'] as $field)$current[$field]=$r[$field.'_id']?Database::query($this->p,'SELECT name FROM master_data WHERE id=?',[$r[$field.'_id']])->fetchColumn():($field==='position'?($r['job_title']??''):'');foreach(['facility','unit'] as $field)$current[$field]=$r[$field.'_id']?Database::query($this->p,'SELECT name FROM organisations WHERE id=?',[$r[$field.'_id']])->fetchColumn():'';$h.='<section class="card"><h2>Perkhidmatan semasa</h2>'.$this->table([$current],['organisation'=>'Organisasi','profession'=>'Profesion','position'=>'Jawatan','grade'=>'Gred','employment_status'=>'Status','facility'=>'Fasiliti','unit'=>'Unit']).'</section>';
        if(Authorization::allowed($this->p,$u,'core.identification.view',$org)){$h.='<details><summary>Nombor pengenalan (terhad)</summary><p>'.self::e($r['identification_cipher']?Crypto::open($r['identification_cipher']):'Belum diisi').'</p>'.self::form('profile',$hidden.self::input('full_name','Nama penuh',$r['full_name']).self::input('phone','Telefon',$r['phone']??'','tel',false).self::input('contact_address','Alamat',$r['contact_address']??'','text',false).self::input('identification_number','Nombor pengenalan').self::input('reason','Sebab')).'</details>';}
        if(Authorization::allowed($this->p,$u,'core.staff.manage',$org))$h.='<section class="card"><h2>Perubahan perkhidmatan</h2><p>Tarikh baharu mesti sama atau selepas tarikh rekod semasa dan tidak melebihi hari ini. Pertukaran rentas scope memerlukan pentadbir yang berkuasa pada kedua-dua organisasi.</p>'.self::form('employment',$hidden.$this->employmentFields($r).self::input('effective_from','Tarikh kuat kuasa',gmdate('Y-m-d'),'date').self::input('reason','Sebab perubahan')).'</section>';
        $history=Database::query($this->p,'SELECT h.*,o.name AS organisation_name FROM employment_history h LEFT JOIN organisations o ON o.id=h.organisation_id WHERE h.staff_identity_id=? ORDER BY h.id DESC',[$id])->fetchAll();$h.='<h2>Sejarah perkhidmatan</h2>'.$this->table($history,['effective_from'=>'Dari','effective_until'=>'Hingga (eksklusif)','organisation_name'=>'Organisasi','position_id'=>'Jawatan ID','grade_id'=>'Gred ID','change_reason'=>'Sebab']);$creds=Database::query($this->p,'SELECT c.*,m.name AS regulator FROM professional_credentials c JOIN master_data m ON m.id=c.regulator_id WHERE staff_identity_id=?',[$id])->fetchAll();$h.='<h2>Maklumat profesional</h2>'.$this->table($creds,['regulator'=>'Regulator','registration_number'=>'No. pendaftaran','additional_credentials'=>'Kelayakan tambahan']).self::form('credential',$hidden.$this->select('regulator_id','Regulator',$this->masters('regulator'),null,true).self::input('registration_number','No. pendaftaran').self::input('additional_credentials','Kelayakan tambahan','','text',false),'Tambah kelayakan');
        if(!$r['user_id']&&Authorization::allowed($this->p,$u,'core.staff.manage',$org)){$h.='<h2>Pengesahan registry</h2>'.self::form('profile',$hidden.self::input('full_name','Nama penuh',$r['full_name']).self::input('official_email','E-mel rasmi',$r['official_email']??'','email').self::input('reason','Sebab pengesahan')).self::form('registry_status',$hidden.$this->select('status','Status registry',[['id'=>'PRE_VERIFIED','name'=>'Pre-verified'],['id'=>'INACTIVE','name'=>'Inactive']],null,true).self::input('reason','Sebab status'));}
