    private function security():string {$this->actor();return '<h2>Tukar kata laluan</h2><p>Semua sesi lama akan tamat selepas pertukaran.</p>'.self::form('password_change',self::input('current_password','Kata laluan semasa','','password').self::input('password','Kata laluan baharu','','password').self::input('confirm_password','Sahkan kata laluan','','password'),'Tukar kata laluan').'<h2>Sahkan / tukar e-mel rasmi</h2>'.self::form('email_change',self::input('email','E-mel rasmi untuk disahkan atau ditukar',$this->user['email'],'email').self::input('current_password','Kata laluan semasa','','password'),'Hantar pengesahan e-mel');}
    private function myOrganisation():string {$this->actor();$org=$this->user['organisation_id'];if(!$org)return '<p>Organisasi belum ditetapkan.</p>';$r=Database::query($this->p,'SELECT name,type,code,address,email,phone,is_active FROM organisations WHERE id=?',[$org])->fetch();$anc=Database::query($this->p,'SELECT o.name,o.type FROM organisations o JOIN organisation_hierarchy h ON h.ancestor_id=o.id WHERE h.descendant_id=? ORDER BY h.depth DESC',[$org])->fetchAll();return $this->table([$r],['name'=>'Organisasi','type'=>'Jenis','address'=>'Alamat','email'=>'E-mel','phone'=>'Telefon','is_active'=>'Aktif']).'<h2>Hierarchy</h2>'.$this->table($anc,['name'=>'Organisasi','type'=>'Jenis']);}
    private function directory():string {
        $this->requireAny('core.staff.view');[$s,$args]=Authorization::scope($this->p,$this->actor(),'core.staff.view','p.organisation_id');$where=[$s];$q=Core::text($_GET['q']??'',190,false);if($q!==''){$where[]='(p.full_name LIKE ? OR p.official_email LIKE ?)';$args[]='%'.$q.'%';$args[]='%'.$q.'%';}
        foreach(['profession_id','position_id','grade_id','facility_id','unit_id'] as $k)if(($_GET[$k]??'')!==''){$where[]='p.'.$k.'=?';$args[]=Core::id($_GET[$k]);}if(($_GET['organisation_id']??'')!==''){$where[]='p.organisation_id IN (SELECT descendant_id FROM organisation_hierarchy WHERE ancestor_id=?)';$args[]=Core::id($_GET['organisation_id']);}if(($_GET['account_status']??'')!==''){$status=$_GET['account_status'];if(!in_array($status,['active','inactive','unclaimed'],true))throw new \InvalidArgumentException('Status tidak sah.');$where[]=$status==='unclaimed'?'u.id IS NULL':($status==='active'?'u.is_active=1':'u.is_active=0');}
        $rows=Database::query($this->p,'SELECT p.staff_identity_id,p.full_name,p.official_email,o.name AS organisation_name,pr.name AS profession,po.name AS position,gr.name AS grade,CASE WHEN u.id IS NULL THEN "UNCLAIMED" WHEN u.is_active=1 THEN "ACTIVE" ELSE "INACTIVE" END AS account_status FROM staff_profiles p LEFT JOIN users u ON u.staff_identity_id=p.staff_identity_id LEFT JOIN organisations o ON o.id=p.organisation_id LEFT JOIN master_data pr ON pr.id=p.profession_id LEFT JOIN master_data po ON po.id=p.position_id LEFT JOIN master_data gr ON gr.id=p.grade_id WHERE '.implode(' AND ',$where).' ORDER BY p.full_name LIMIT 100',$args)->fetchAll();$f=self::input('q','Nama / e-mel',$q,'search',false);foreach(['profession'=>'Profesion','position'=>'Jawatan','grade'=>'Gred'] as $c=>$label)$f.=$this->select($c.'_id',$label,$this->masters($c),$_GET[$c.'_id']??null);$f.=$this->select('organisation_id','PKD / klinik / organisasi',$this->orgs('core.staff.view'),$_GET['organisation_id']??null).$this->select('facility_id','Fasiliti',$this->orgs('core.staff.view'),$_GET['facility_id']??null).$this->select('unit_id','Unit',$this->orgs('core.staff.view'),$_GET['unit_id']??null).$this->select('account_status','Status akaun',[['id'=>'active','name'=>'Aktif'],['id'=>'inactive','name'=>'Tidak aktif'],['id'=>'unclaimed','name'=>'Belum dituntut']],$_GET['account_status']??null);return '<form method="get" class="filters">'.$f.'<button>Cari</button></form><p>Maksimum 100 hasil; gunakan penapis untuk memperincikan carian.</p>'.$this->table($rows,['full_name'=>'Nama','official_email'=>'E-mel','profession'=>'Profesion','position'=>'Jawatan','grade'=>'Gred','organisation_name'=>'Organisasi','account_status'=>'Akaun'],fn($r)=>'<a href="/profile?id='.(int)$r['staff_identity_id'].'">Lihat profil</a>');
    }
    private function importMapping():string {$h='<details><summary>Column mapping (pilihan)</summary><p>Masukkan nama header asal bagi medan yang sepadan. Kosongkan jika header sudah mengikut template.</p>';foreach(Imports::HEADERS as $column)$h.=self::input('map_'.$column,'Header asal → '.$column,'','text',false);return $h.'</details>';}
    private function registryList():string {
        [$scope,$args]=Authorization::scope($this->p,$this->actor(),'core.staff.manage','p.organisation_id');$q=Core::text($_GET['q']??'',100,false);$status=Core::text($_GET['status']??'',30,false);$where=$scope.' AND (p.full_name LIKE ? OR p.official_email LIKE ?)';$args[]='%'.$q.'%';$args[]='%'.$q.'%';if($status!==''){if(!in_array($status,['PRE_VERIFIED','CLAIMED','INACTIVE'],true))throw new \InvalidArgumentException('Status registry tidak sah.');$where.=' AND r.status=?';$args[]=$status;}
        $page=max(1,min(10000,(int)($_GET['page']??1)));$offset=($page-1)*25;$sort=Core::text($_GET['sort']??'name',15);$order=['name'=>'p.full_name','recent'=>'p.staff_identity_id DESC'];if(!isset($order[$sort]))throw new \InvalidArgumentException('Sorting tidak sah.');$count=(int)Database::query($this->p,'SELECT COUNT(*) FROM staff_profiles p JOIN staff_registry r ON r.staff_identity_id=p.staff_identity_id WHERE '.$where,$args)->fetchColumn();
        $rows=Database::query($this->p,'SELECT p.staff_identity_id,p.full_name,p.official_email,o.name AS organisation,r.status,CASE WHEN u.id IS NULL THEN "UNCLAIMED" WHEN u.is_active=1 THEN "ACTIVE" ELSE "INACTIVE" END AS account_status FROM staff_profiles p JOIN staff_registry r ON r.staff_identity_id=p.staff_identity_id LEFT JOIN users u ON u.staff_identity_id=p.staff_identity_id LEFT JOIN organisations o ON o.id=p.organisation_id WHERE '.$where.' ORDER BY '.$order[$sort].' LIMIT 25 OFFSET '.$offset,$args)->fetchAll();
        $h='<h2>Staff Registry & Account Activation</h2><p>Satu identiti kekal. Admin-preverified staf menerima jemputan untuk mencipta kata laluan sendiri. Permohonan lain menunggu approval Admin sebelum jemputan. <a href="/claim">Mohon semula jemputan</a>. Akaun aktif tidak dioverwrite.</p><form method="get" class="filters">'.self::input('q','Nama/e-mel',$q,'search',false).$this->select('status','Status registry',array_map(fn($v)=>['id'=>$v,'name'=>$v],['PRE_VERIFIED','CLAIMED','INACTIVE']),$status).$this->select('sort','Susun',[['id'=>'name','name'=>'Nama'],['id'=>'recent','name'=>'Terbaharu']],$sort).'<button>Cari</button></form>';
        foreach($rows as &$row){$v=Accounts::invitationStatus($this->p,$this->actor(),(int)$row['staff_identity_id']);$row['invitation']=$v['invitation'];$row['delivery']=$v['delivery'];}unset($row);$h.=$this->table($rows,['full_name'=>'Nama','official_email'=>'E-mel','organisation'=>'Organisasi','status'=>'Registry','account_status'=>'Akaun','delivery'=>'Penghantaran','invitation'=>'Jemputan'],fn($r)=>'<a href="/profile?id='.(int)$r['staff_identity_id'].'">Profil/history</a>'.($r['account_status']==='UNCLAIMED'&&$r['status']==='PRE_VERIFIED'?self::form('staff_invite','<input type="hidden" name="staff_id" value="'.(int)$r['staff_identity_id'].'"><input type="hidden" name="reason" value="Admin invitation resend">','Hantar / hantar semula jemputan'):''));$h.='<nav aria-label="Pagination">'.$count.' rekod · Halaman '.$page.' ';foreach(['Sebelum'=>$page-1,'Seterusnya'=>$page+1] as $label=>$n)if($n>=1&&($n-1)*25<$count){$params=$_GET;$params['page']=$n;$h.='<a href="?'.self::e(http_build_query($params)).'">'.$label.'</a> ';}return $h.'</nav>';
    }
    private function activationRecoveryPanel():string {
        $email=Core::text($_GET['activation_email']??'',190,false);$h='<section class="card"><h2>Semak &amp; sambung pengaktifan staf</h2><p>Semak Staff ID sebelum menghantar jemputan. Akaun yang sudah wujud tidak direset atau diaktifkan melalui fungsi ini.</p><form method="get">'.self::input('activation_email','E-mel yang dijemput',$email,'email').'<button>Semak rekod</button></form>';
        if($email!==''){$rows=StaffActivationRecovery::inspect($this->p,$this->actor(),$email);if(!$rows)$h.='<p>Tiada rekod dalam skop anda. Rujuk Admin yang diberi kuasa.</p>';foreach($rows as $r){$h.='<article class="registration-row"><h3>'.self::e($r['full_name']).'</h3><p>Staff ID: '.(int)$r['staff_identity_id'].' · Registry: '.self::e($r['registry']).' · Akaun: '.self::e($r['account_state']).'</p>'.($r['login_email']?'<p>E-mel login sedia ada: '.self::e($r['login_email']).'</p>':'').'<a href="/profile?id='.(int)$r['staff_identity_id'].'">Semak profil asal</a>';if($r['ready_to_resume'])$h.='<p>Sahkan identiti dan nama rekod ini sebelum menghantar. E-mel tidak akan dipindahkan daripada Staff ID lain.</p>'.self::form('activation_resume','<input type="hidden" name="staff_id" value="'.(int)$r['staff_identity_id'].'"><input type="hidden" name="email" value="'.self::e($email).'">'.self::input('confirmed_name','Taip nama penuh yang disemak').self::input('reason','Sebab / bukti semakan Admin'),'Sambung rekod & hantar jemputan');else $h.='<p>BLOCKED untuk password pertama. Semak akaun sedia ada/approval/rekod bercanggah; jangan cipta akaun kedua.</p>';$h.='</article>';}}
        return $h.'</section>';
    }
    private function registry():string {
        if(isset($_GET['facility_catalog']))return FacilityDirectory::render($this->p,$this->actor());
        $this->requireAny('core.staff.manage');$h='<p><a href="/registry?facility_catalog=1">Direktori fasiliti Kelantan — preview/import berkelompok</a></p>'.$this->activationRecoveryPanel().$this->registryList().'<h2>Daftar staf — nama dan e-mel sahaja</h2><p>Organisasi routing diambil daripada konteks Admin yang dibenarkan. Maklumat profil lain pilihan selepas activation.</p>'.self::form('preverify',self::input('full_name','Nama penuh').self::input('official_email','E-mel','','email'),'Daftar & jemput staf');if($this->can('core.registry.import')){$h.='<h2>Import CSV / XLSX</h2><p>UTF-8; maksimum 5 MB dan 1000 staf. XLSX: worksheet pertama, tanpa formula atau macro. Header: '.self::e(implode(', ',Imports::HEADERS)).'. Nilai rujukan menggunakan ID daripada organisasi/master data.</p>'.self::form('import_preview',self::input('file','Fail import','','file').$this->importMapping(),'Preview import',true);if(isset($_GET['batch'])){$id=Core::id($_GET['batch']);$b=Imports::batch($this->p,$this->actor(),$id);if(($_GET['export']??'')==='csv'){header('Content-Type: text/csv; charset=UTF-8');header('Content-Disposition: attachment; filename=staff-import-report.csv');header('Cache-Control: no-store');$out=fopen('php://output','w');fputcsv($out,['source_row','result','staff_identity_id']);foreach(Database::query($this->p,'SELECT source_row,result,staff_identity_id FROM staff_import_items WHERE batch_id=? ORDER BY source_row',[$id])->fetchAll() as $item){foreach($item as &$v)if(is_string($v)&&preg_match('/\A[=+@-]/',$v))$v="'".$v;unset($v);fputcsv($out,array_values($item));}fclose($out);exit;}$rows=Database::query($this->p,'SELECT source_row,result,staff_identity_id FROM staff_import_items WHERE batch_id=? ORDER BY source_row',[$id])->fetchAll();$h.='<h2>Preview / keputusan #'.$id.'</h2><a href="/registry?batch='.$id.'&amp;export=csv">Download result CSV</a>'.$this->table($rows,['source_row'=>'Baris','result'=>'Keputusan','staff_identity_id'=>'Staff ID']);$preview=Database::query($this->p,'SELECT source_row,data_json FROM staff_import_items WHERE batch_id=? ORDER BY source_row',[$id])->fetchAll();$pr=[];foreach($preview as $item)$pr[]=['row'=>$item['source_row'],...json_decode($item['data_json'],true)];$h.=$this->table($pr,['row'=>'Baris','full_name'=>'Nama','official_email'=>'E-mel','organisation_id'=>'Organisasi ID']);if($b['status']==='PREVIEW')$h.=self::form('import_commit','<input type="hidden" name="batch_id" value="'.$id.'">','Sahkan import baris sah');}}return $h;
    }
    private function reviews():string {$this->requireAny('core.registrations.review');[$s,$a]=Authorization::scope($this->p,$this->actor(),'core.registrations.review','r.organisation_id');$rows=Database::query($this->p,'SELECT r.*,o.name AS organisation_name FROM registration_requests r JOIN organisations o ON o.id=r.organisation_id WHERE '.$s.' ORDER BY r.id DESC LIMIT 100',$a)->fetchAll();return '<p><a class="button" href="/registration-admin?tab=email_approvals">Kelulusan E-mel Tambahan</a></p>'.$this->table($rows,['full_name'=>'Nama','email'=>'E-mel','organisation_name'=>'Organisasi','status'=>'Status','reason'=>'Sebab'],function($r){return $r['status']==='PENDING_VERIFICATION'?self::form('review','<input type="hidden" name="request_id" value="'.(int)$r['id'].'">'.$this->select('decision','Keputusan',[['id'=>'APPROVED','name'=>'Approve'],['id'=>'REJECTED','name'=>'Reject'],['id'=>'REQUEST_CORRECTION','name'=>'Request correction']],null,true).self::input('reason','Sebab'),'Simpan keputusan'):'';});}
